test_that("results validate common quantities", {s<-bench_fixture();r<-oracle_result(s);expect_invisible(validate_sblrbench_result(r,s));expect_identical(rownames(r$estimates$effects),s$data$marker_ids);expect_identical(colnames(r$estimates$pip),s$data$trait_names);expect_null(new_sblrbench_result("x")$estimates$effects);expect_null(new_sblrbench_result("x",native_fit=list(pi_mean=1),keep_native_fit=FALSE)$native_fit);bad<-r;bad$estimates$effects<-bad$estimates$effects[-1,,drop=FALSE];expect_error(validate_sblrbench_result(bad,s),"dimensions")})
